package com.jackbhai.omnitools.nativ.games;

import java.util.Random;

/** Pure-Java Lights Out (5x5). Boards are generated by applying random
 *  presses to a solved board, so every generated board is solvable. */
public final class LightsOutLogic {
    public static final int N = 5;
    private final boolean[] on = new boolean[N * N];
    private int moves;

    public LightsOutLogic(Random rnd, int presses) {
        // start solved (all off), apply random presses -> guaranteed solvable
        for (int i = 0; i < presses; i++) press(rnd.nextInt(N), rnd.nextInt(N));
        if (isSolved()) press(0, 0); // never hand out a pre-solved board
        moves = 0;
    }

    /** Test/secondary constructor from an explicit board. */
    public LightsOutLogic(boolean[] board) {
        System.arraycopy(board, 0, on, 0, N * N);
    }

    public boolean get(int r, int c) { return on[r * N + c]; }
    public int moves() { return moves; }

    public void press(int r, int c) {
        toggle(r, c); toggle(r - 1, c); toggle(r + 1, c); toggle(r, c - 1); toggle(r, c + 1);
        moves++;
    }
    private void toggle(int r, int c) {
        if (r < 0 || c < 0 || r >= N || c >= N) return;
        on[r * N + c] = !on[r * N + c];
    }
    public boolean isSolved() {
        for (boolean b : on) if (b) return false;
        return true;
    }
    public int litCount() { int n = 0; for (boolean b : on) if (b) n++; return n; }
}
